CREATE TABLE "DiscoveredProblem" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"title" TEXT NOT NULL,"normalizedProblemStatement" TEXT NOT NULL,"problemFingerprint" TEXT NOT NULL,"category" TEXT NOT NULL,"severity" INTEGER NOT NULL,"evidenceCount" INTEGER NOT NULL DEFAULT 0,"sourceDiversity" INTEGER NOT NULL DEFAULT 0,"urgency" INTEGER NOT NULL,"affectedAudience" TEXT NOT NULL,"affectedMarket" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'potential',"confidence" INTEGER NOT NULL,"recurringScore" INTEGER NOT NULL DEFAULT 0,"recurringExplanation" JSONB NOT NULL,"opportunityAnalysisId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "DiscoveredProblem_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "DiscoveredProblem_opportunityAnalysisId_key" ON "DiscoveredProblem"("opportunityAnalysisId"); CREATE UNIQUE INDEX "DiscoveredProblem_userId_problemFingerprint_key" ON "DiscoveredProblem"("userId","problemFingerprint"); CREATE INDEX "DiscoveredProblem_userId_createdAt_idx" ON "DiscoveredProblem"("userId","createdAt"); CREATE INDEX "DiscoveredProblem_userId_status_idx" ON "DiscoveredProblem"("userId","status"); CREATE INDEX "DiscoveredProblem_userId_category_idx" ON "DiscoveredProblem"("userId","category"); CREATE INDEX "DiscoveredProblem_userId_recurringScore_idx" ON "DiscoveredProblem"("userId","recurringScore");
CREATE TABLE "ProblemEvidence" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"problemId" TEXT NOT NULL,"sourceId" TEXT,"externalReference" TEXT,"title" TEXT NOT NULL,"summary" TEXT NOT NULL,"observedAt" TIMESTAMP(3) NOT NULL,"sourceType" TEXT NOT NULL,"fingerprint" TEXT NOT NULL,"evidenceConfidence" INTEGER NOT NULL,"severity" INTEGER NOT NULL,"urgency" INTEGER NOT NULL,"solutionFit" INTEGER NOT NULL,"businessValueHypothesis" INTEGER NOT NULL,"sourceReference" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ProblemEvidence_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "ProblemEvidence_userId_fingerprint_key" ON "ProblemEvidence"("userId","fingerprint"); CREATE INDEX "ProblemEvidence_userId_problemId_observedAt_idx" ON "ProblemEvidence"("userId","problemId","observedAt"); CREATE INDEX "ProblemEvidence_userId_sourceId_idx" ON "ProblemEvidence"("userId","sourceId");
CREATE TABLE "Prospect" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"type" TEXT NOT NULL,"displayName" TEXT,"organizationName" TEXT,"publicReference" TEXT,"sourceReference" TEXT,"roleCategory" TEXT,"evidenceCount" INTEGER NOT NULL DEFAULT 0,"fingerprint" TEXT NOT NULL,"confidence" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Prospect_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Prospect_userId_fingerprint_key" ON "Prospect"("userId","fingerprint"); CREATE INDEX "Prospect_userId_createdAt_idx" ON "Prospect"("userId","createdAt"); CREATE INDEX "Prospect_userId_type_idx" ON "Prospect"("userId","type");
CREATE TABLE "ProspectProblem" ("prospectId" TEXT NOT NULL,"problemId" TEXT NOT NULL,"evidenceCount" INTEGER NOT NULL DEFAULT 0,"qualificationScore" INTEGER NOT NULL DEFAULT 0,"qualificationLevel" TEXT NOT NULL DEFAULT 'LOW',"reasons" JSONB NOT NULL,"confidence" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ProspectProblem_pkey" PRIMARY KEY ("prospectId","problemId"));
CREATE INDEX "ProspectProblem_problemId_qualificationScore_idx" ON "ProspectProblem"("problemId","qualificationScore");
ALTER TABLE "DiscoveredProblem" ADD CONSTRAINT "DiscoveredProblem_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "DiscoveredProblem" ADD CONSTRAINT "DiscoveredProblem_opportunityAnalysisId_fkey" FOREIGN KEY ("opportunityAnalysisId") REFERENCES "OpportunityRecord"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "ProblemEvidence" ADD CONSTRAINT "ProblemEvidence_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ProblemEvidence" ADD CONSTRAINT "ProblemEvidence_problemId_fkey" FOREIGN KEY ("problemId") REFERENCES "DiscoveredProblem"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Prospect" ADD CONSTRAINT "Prospect_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ProspectProblem" ADD CONSTRAINT "ProspectProblem_prospectId_fkey" FOREIGN KEY ("prospectId") REFERENCES "Prospect"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "ProspectProblem" ADD CONSTRAINT "ProspectProblem_problemId_fkey" FOREIGN KEY ("problemId") REFERENCES "DiscoveredProblem"("id") ON DELETE CASCADE ON UPDATE CASCADE;